import React from "react";
import { AbsoluteFill, interpolate, OffthreadVideo, staticFile, useCurrentFrame } from "remotion";
import { z } from "zod";
import { defineEffect, type EffectDef } from "../../core/effect";
import type { Timeline } from "../../core/timing";

/** A pre-rendered picture (e.g. ray-traced in Blender) played as the reel's video, with a fade to black at the end. */
const clipSchema = z.object({
  /** video under assets/ (git-ignored media, regenerated by its script) */
  src: z.string(),
  /** fade to black (seconds since the start of the reel) */
  fade: z.tuple([z.number(), z.number()]).optional(),
});
type P = z.output<typeof clipSchema>;

function Clip({ params, tl, offset }: { params: P; tl: Timeline; offset: number }) {
  const frame = useCurrentFrame() + offset;
  const t = frame / tl.fps;
  const black = params.fade ? interpolate(t, params.fade, [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }) : 0;
  return (
    <AbsoluteFill style={{ backgroundColor: "black" }}>
      <OffthreadVideo src={staticFile(params.src)} startFrom={offset} muted style={{ width: "100%", height: "100%", objectFit: "cover" }} />
      <AbsoluteFill style={{ backgroundColor: "black", opacity: black * black * (3 - 2 * black) }} />
    </AbsoluteFill>
  );
}

export const clip: EffectDef = defineEffect({
  about: "Plays a pre-rendered video (e.g. a Blender ray-traced render) as the picture, with an optional fade to black.",
  schema: clipSchema,
  component: ({ params, tl }) => <Clip params={params} tl={tl} offset={0} />,
});

export const clipContinue: EffectDef = defineEffect({
  about: "Continues the clip through the transform phase.",
  schema: clipSchema,
  component: ({ params, tl }) => <Clip params={params} tl={tl} offset={tl.transform.start} />,
});
